                    CREATE TRIGGER observe AFTER UPDATE OF balance ON accounts WHEN NEW.name='a' BEGIN
                        {insert}
                        INSERT INTO observed SELECT tenant,{observed} FROM {table} WHERE {selector};
                        {f'DELETE FROM {table} WHERE {selector};' if cleanup else ''}
                    END;
