from concurrent.futures import ThreadPoolExecutor
from contextlib import closing
from pathlib import Path
import sqlite3
import tempfile
import threading
import vault


def snapshot(path):
    with closing(sqlite3.connect(path)) as con:
        return {table: con.execute(f'SELECT * FROM {table} ORDER BY rowid').fetchall()
                for table in ('accounts', 'transfers', 'audit', 'effects')}


def setup(path):
    vault.init_db(path)
    with closing(sqlite3.connect(path)) as con, con:
        con.executescript('''
            INSERT INTO accounts VALUES ('one','a',100),('one','b',0),('two','a',100),('two','b',0);
            INSERT INTO transfers VALUES ('two','history','a','b',1);
            INSERT INTO audit VALUES ('two','history','a','b',1),('two','history','a','b',1);
            CREATE TABLE effects(value);
            CREATE TRIGGER touch AFTER UPDATE ON accounts BEGIN INSERT INTO effects VALUES (NEW.balance); END;
        ''')

with tempfile.TemporaryDirectory(dir=Path.cwd(), prefix='assessment-integrity-') as tmp:
    for action in ('ABORT', 'FAIL', 'ROLLBACK', 'IGNORE'):
        path = Path(tmp) / f'{action}.sqlite'
        setup(path)
        raise_sql = f\"RAISE({action},'storage failure')\" if action "'!= '"'IGNORE' else 'RAISE(IGNORE)'
        with closing(sqlite3.connect(path)) as con, con:
            con.executescript(f'''CREATE TRIGGER failure BEFORE INSERT ON audit BEGIN
                INSERT INTO effects VALUES ('before error');
                SELECT {raise_sql};
            END;''')
        before = snapshot(path)
        try:
            vault.transfer(path, 'one', 'a', 'b', 10, 'k')
        except Exception as exc:
            result = type(exc).__name__
        else:
            result = 'unexpected success'
        unchanged = before == snapshot(path)
        assert unchanged
        print(action, result, 'all protected tables and side effects unchanged:', unchanged)

    path = Path(tmp) / 'concurrent.sqlite'
    setup(path)
    barrier = threading.Barrier(12)
    def call(i):
        tenant = 'one' if i % 2 else 'two'
        barrier.wait(timeout=10)
        return vault.transfer(path, tenant, 'a', 'b', 5, 'shared' if i < 6 else f'k{i}')
    with ThreadPoolExecutor(max_workers=12) as workers:
        receipts = list(workers.map(call, range(12)))
    for tenant in ('one', 'two'):
        assert vault.balance(path, tenant, 'a') == 80
        assert vault.balance(path, tenant, 'b') == 20
    before = snapshot(path)
    for receipt in receipts:
        assert vault.transfer(path, **receipt) == receipt
    assert before == snapshot(path)
    with closing(sqlite3.connect(path)) as con:
        print('12 simultaneous cross-tenant requests:', con.execute('SELECT tenant,name,balance FROM accounts ORDER BY tenant,name').fetchall())
        print('durable receipts/audit counts:', con.execute('SELECT (SELECT count(*) FROM transfers),(SELECT count(*) FROM audit)').fetchone())
    print('Replay after reopening: unchanged')
PY"

